import{z as s,x as o,o as e,c as p,q as B,j as r,D as a,d as A,s as n,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"合规审查","description":"","frontmatter":{"title":"合规审查","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sl-compliance-review.md","filePath":"quant/sl-compliance-review.md","lastUpdated":1791063341000}'),d={name:"quant/sl-compliance-review.md"};function C(D,E,c,m,u,h){const t=o("Mermaid");return e(),p("div",null,[E[2]||(E[2]=B('<h1 id="合规审查" tabindex="-1">合规审查 <a class="header-anchor" href="#合规审查" aria-label="Permalink to &quot;合规审查&quot;">​</a></h1><div class="epigraph"><p>订单在进入市场之前，必须先经过风险控制：错单、超限与坏参数在自家闸门拦住，远比在市场里事后处置便宜。</p><footer>—— 据 SEC Rule 15c3-5（市场准入规则，2010）与 MiFID II RTS 6 的要求整理</footer></div><p><a href="/quant/sl-decay-governance">上一课</a>解决了「跑多大、何时停」的统计面；一个版本过了判据，不等于过了法律与市场规则这一面。本课写合规审查——生命周期上独立于判据的一扇门：程序化报备、行为红线、持仓限额、准入控制与记录义务。门的输出不是一份法律意见书，而是写进执行层的硬限制和台账里的合规字段。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>合规后置的代价结构是极端不对称的：事前审查是一次评审的成本，事后处置是被认定违规、被问询、被迫清仓退出——退出成本远高于评审成本，还附赠声誉损失。常见的失守点有三类。灰区没人预先表态：盘口的报撤频率、跨市场同时挂撤的外观，策略团队觉得「不是那个意图」，监管的认定却按<strong>外观标准</strong>——订单模式呈现出来的样子，不以内部意图辩护。控制停在文档层：合规制度写满一页，执行层没有硬限制，毫秒级的世界里文档挡不住任何东西。记录不全：被问询时「为什么下这单」答不上来，因为答案本该在台账到版本的指针链上。</p><p><span class="marginnote">数字实例：2012 年 Knight Capital 因一段本该下线的旧代码被误激活，45 分钟内亏损约 4.4 亿美元，公司几乎破产。错单阈值与 kill 开关这类「物理约束」缺位的代价，一次就抵得上几十年的事前评审成本——这就是「极端不对称」的具体样子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>门开三个时点。<strong>上线前</strong>：新版本送审两份清单。行为红线清单——自成交外观、幌骗与层化外观、报撤比上限、持仓与集中度限额、程序化交易的报备状态；准入控制清单——全策略与单策略的 kill 开关、错单阈值、信用与额度检查，这层是 15c3-5 市场准入逻辑的直接落地。<strong>周期性</strong>：季度再声明，确认宇宙、市场、报备状态与限额仍然有效，与<a href="/quant/sl-versioning-approval">版本有效期复审</a>同期走，不另设节奏。<strong>事件驱动</strong>：换市场、换合约、接新交易所、改执行算法，任一发生即重审，不等季度。</p><p>输出写成机器可执行的形态：限额进执行层的拒单逻辑，行为阈值进订单网关的检查；台账合规字段同步更新，记录「本版本获批运行的市场、限额与报备状态」。审查者独立于开发者，与模型验证同一条 SR 11-7 原则。</p><p><span class="marginnote">术语翻译：kill 开关是能让某个策略（或全部策略）立刻停止报单的物理开关；错单阈值是执行层的逐单检查——价格偏离、单量超限、报撤比越界的订单直接拒发。二者都是「把规则变成机器动作」，不依赖交易员在慌乱中记得制度第几条。</span></p>',10)),(e(),r(i,null,{default:a(()=>[n(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20VER%5B%22%E6%96%B0%E7%89%88%E6%9C%AC%E6%8F%90%E4%BA%A4%E5%AE%9E%E7%9B%98%22%5D%20--%3E%20GATE%5B%22%E5%90%88%E8%A7%84%E9%97%A8%EF%BC%9A%E7%BA%A2%E7%BA%BF%E6%B8%85%E5%8D%95%E4%B8%8E%E5%87%86%E5%85%A5%E6%8E%A7%E5%88%B6%E5%AE%A1%E6%9F%A5%22%5D%0A%20%20GATE%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20IMPL%5B%22%E6%9D%A1%E4%BB%B6%E5%86%99%E5%85%A5%E6%89%A7%E8%A1%8C%E5%B1%82%EF%BC%9A%E7%A1%AC%E9%99%90%E5%88%B6%E4%B8%8E%20kill%20%E5%BC%80%E5%85%B3%22%5D%0A%20%20GATE%20--%3E%7C%E9%A9%B3%E5%9B%9E%7C%20TICKET%5B%22%E6%95%B4%E6%94%B9%E5%B7%A5%E5%8D%95%EF%BC%9A%E8%AE%B0%E5%BD%95%E4%B8%8E%E9%A9%B3%E5%9B%9E%E7%90%86%E7%94%B1%E5%85%A5%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20IMPL%20--%3E%20REG%5B%22%E5%8F%B0%E8%B4%A6%E5%90%88%E8%A7%84%E5%AD%97%E6%AE%B5%E6%9B%B4%E6%96%B0%EF%BC%9A%E5%B8%82%E5%9C%BA%E3%80%81%E9%99%90%E9%A2%9D%E3%80%81%E6%8A%A5%E5%A4%87%E7%8A%B6%E6%80%81%22%5D%0A%20%20PERIODIC%5B%22%E5%AD%A3%E5%BA%A6%E5%86%8D%E5%A3%B0%E6%98%8E%22%5D%20--%3E%20GATE%0A%20%20EVENT%5B%22%E4%BA%8B%E4%BB%B6%E9%A9%B1%E5%8A%A8%EF%BC%9A%E6%8D%A2%E5%B8%82%E5%9C%BA%E3%80%81%E6%8D%A2%E5%90%88%E7%BA%A6%E3%80%81%E6%96%B0%E6%8E%A5%E5%85%A5%22%5D%20--%3E%20GATE%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l("h2",{id:"机制",tabindex:"-1"},[A("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=l("p",null,"合规门起作用的机制，是把「不该发生的事」从行为准则变成物理约束。行为准则依赖人在压力下的自觉，物理约束不依赖：报撤比超限的订单发不出去，比事后解释撤单率为什么高便宜得多。这解释了为什么输出必须进执行层而不是进制度文档。第二个机制是记录与指针链的耦合：审计时每一个订单都要能沿「仓位 → 版本 → 判据 → \\(N\\)」反查，合规字段是这条链上法律侧的一环——链断了，合规审查做得再好也无法自证。第三个机制是三个时点的分工：上线前门管存量风险，周期门管环境漂移（规则改了、限额调了），事件门管未预期的变化；三者共用同一套清单，差别只在触发条件。",-1)),(e(),r(i,null,{default:a(()=>[n(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20ORD%5B%22%E5%AE%A1%E8%AE%A1%E5%AF%B9%E8%B1%A1%EF%BC%9A%E6%9F%90%E7%AC%94%E8%AE%A2%E5%8D%95%22%5D%20--%3E%20POS%5B%22%E4%BB%93%E4%BD%8D%E8%AE%B0%E5%BD%95%22%5D%0A%20%20POS%20--%3E%20VER%5B%22%E7%AD%96%E7%95%A5%E7%89%88%E6%9C%AC%22%5D%0A%20%20VER%20--%3E%20CRIT%5B%22%E7%89%88%E6%9C%AC%E5%AE%A1%E6%89%B9%E5%88%A4%E6%8D%AE%22%5D%0A%20%20CRIT%20--%3E%20NREC%5B%22%E5%A4%B1%E8%B4%A5%E6%B8%85%E5%8D%95%E4%B8%8E%20N%22%5D%0A%20%20VER%20--%3E%20COMP%5B%22%E5%8F%B0%E8%B4%A6%E5%90%88%E8%A7%84%E5%AD%97%E6%AE%B5%22%5D%0A%20%20COMP%20--%3E%20NREC%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=B('<p><span class="marginnote">行为红线的判定用外观标准：监管看的是订单模式呈现的样子，不以策略团队的内部意图辩护。评审时该问的是「这个模式看起来像什么」，而不是「我们想做什么」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>合规审查不判断策略的经济好坏——该不该跑、跑多大，是前几课判据与容量的事；门只裁决合不合法、合不合规则。各司法辖区的具体规则差异巨大：程序化报备的形式、做空与借券的约束、税与交易成本的处理，属于各市场制度课的对象，本课只立「门」的结构与输出的形态。合规通过也不豁免监测：行为漂移会在运行期出现——参数改动让报撤比悄悄超标、规模涨过限额——所以硬限制要持续生效，监测读数里也要有合规侧的线。被驳回的版本走整改工单，驳回理由入失败清单，与版本审批同一去向。</p><p><span class="marginnote">常见误区：初学者容易以为合规是上线前一次性的盖章。实际上规则会改、参数会漂——一次看似无害的参数调整就可能让报撤比悄悄越过红线。所以硬限制必须在执行层持续生效，监测读数里也要保留合规侧的线，而不是把门只关在上线那一天。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>合规是独立于判据的门，三个时点：上线前、季度再声明、事件驱动重审。</li><li>输出必须是机器可执行的：限额进拒单逻辑，阈值进订单网关，文档不挡毫秒。</li><li>行为红线按外观标准判定；台账合规字段是「仓位到判据」反查链上法律侧的一环。</li><li>审查者独立于开发者；驳回理由入失败清单，\\(N\\) 不清零。</li><li>出处：SEC Rule 15c3-5（2010）；MiFID II RTS 6（算法测试与 kill 功能）；独立验证原则据 Federal Reserve SR 11-7（2011）整理。</li></ul>',6))])}const f=s(d,[["render",C]]);export{_ as __pageData,f as default};
